// 全局变量定义
int fb = 0;
int ret = 0;
struct fb_var_screeninfo var;
struct fb_fix_screeninfo fix;
unsigned char *pc = NULL;
unsigned int *pi = NULL;
unsigned int bytes = 0;
unsigned long offset = 0;


// 双缓冲绘制函数
// 双缓冲绘制函数
void draw_point_buffer(unsigned char *buffer, int x, int y, int color)
{
    if (x < 0 || x >= var.xres || y < 0 || y >= var.yres)
        return;

    unsigned long offset = x * bytes + y * fix.line_length;
    unsigned int *pi = (unsigned int *)(buffer + offset);
    *pi = color;
}

void draw_rectangle_buffer(unsigned char *buffer, int x1, int y1, int x2, int y2, int color)
{
    for (int i = x1; i <= x2; i++)
        for (int j = y1; j <= y2; j++)
            draw_point_buffer(buffer, i, j, color);
}

void draw_pic_buffer(unsigned char *buffer, int x, int y, int logo_w, int logo_h, const unsigned char *p)
{
    int i, j;
    unsigned char red, green, blue;
    unsigned int color;

    for (j = 0; j < logo_h; j++)
    {
        for (i = 0; i < logo_w; i++)
        {
            red = *p++;
            green = *p++;
            blue = *p++;
            color = red << 16 | green << 8 | blue;
            draw_point_buffer(buffer, x + i, y + j, color);
        }
    }
}

void draw_game_info_buffer(unsigned char *buffer, struct game_control *game,
                           struct warplane *player, struct boss *boss, int screen_width)
{
    // 绘制血量条
    int hp_bar_x = 20;
    int hp_bar_y = 20;
    int hp_bar_width = 200;
    int hp_bar_height = 20;

    // 血量条背景（红色）
    draw_rectangle_buffer(buffer, hp_bar_x, hp_bar_y,
                          hp_bar_x + hp_bar_width, hp_bar_y + hp_bar_height,
                          0xFF0000);

    // 当前血量（绿色）
    if (player->HP > 0)
    {
        int current_hp_width = (player->HP * hp_bar_width) / player->maxHP;
        draw_rectangle_buffer(buffer, hp_bar_x, hp_bar_y,
                              hp_bar_x + current_hp_width, hp_bar_y + hp_bar_height,
                              0x00FF00);
    }

    // 血量文字
    char hp_text[50];
    snprintf(hp_text, sizeof(hp_text), "HP: %d/%d", player->HP, player->maxHP);

    // 分数
    char score_text[50];
    snprintf(score_text, sizeof(score_text), "SCORE: %d", game->player_score);

    // 绘制分数（右上角）
    int score_x = screen_width - 200;
    int score_y = 20;
    // 这里需要实现draw_text_buffer函数，或者用像素绘制文字

    // 绘制BOSS血量（如果BOSS存在）
    if (boss->alive)
    {
        int boss_hp_bar_x = screen_width / 2 - 150;
        int boss_hp_bar_y = 50;
        int boss_hp_bar_width = 300;
        int boss_hp_bar_height = 15;

        // BOSS血量条背景
        draw_rectangle_buffer(buffer, boss_hp_bar_x, boss_hp_bar_y,
                              boss_hp_bar_x + boss_hp_bar_width,
                              boss_hp_bar_y + boss_hp_bar_height,
                              0x666666);

        // BOSS当前血量
        int boss_current_hp_width = (boss->HP * boss_hp_bar_width) / boss->maxHP;
        draw_rectangle_buffer(buffer, boss_hp_bar_x, boss_hp_bar_y,
                              boss_hp_bar_x + boss_current_hp_width,
                              boss_hp_bar_y + boss_hp_bar_height,
                              0xFF4444);
    }
}

void draw_rectangle_alpha(int x1, int y1, int x2, int y2, int color, int alpha) {
    // alpha: 0-255，0完全透明，255完全不透明
    if (alpha <= 0) return;
    if (alpha >= 255) {
        draw_rectangle(x1, y1, x2, y2, color);
        return;
    }

    // 简化的透明度混合（实际项目中应该使用更精确的alpha混合）
    for (int i = x1; i <= x2; i++) {
        for (int j = y1; j <= y2; j++) {
            // 这里简化处理，实际应该读取原像素颜色并进行混合
            draw_point(i, j, color);
        }
    }
}


// 基本的绘图函数
void draw_point(int x, int y, int color)
{   
    // 添加边界检查
    if (x < 0 || x >= var.xres || y < 0 || y >= var.yres)
        return;
    
    offset = x * bytes + y * fix.line_length;
    pi = (unsigned int *)(pc + offset);
    *pi = color;
}

void draw_rectangle(int x1, int y1, int x2, int y2, int color)
{   
    int i = 0, j = 0;
    
    for(i = x1; i <= x2; i++)
        for(j = y1; j <= y2; j++)
            draw_point(i, j, color);
}

// 绘制圆形函数（在warplane.h中声明了但之前可能没有实现）
void draw_circle(int x, int y, int r, int color)
{
    int i, j;
    for(i = x - r; i <= x + r; i++)
        for(j = y - r; j <= y + r; j++)
            if((i - x)*(i - x) + (j - y)*(j - y) <= r * r)
                draw_point(i, j, color);
}

void draw_pic(int x,int y, int logo_w, int logo_h, const unsigned char *p)
{   
    int i = 0, j = 0; 
    unsigned char red = 0;
    unsigned char green = 0;
    unsigned char blue = 0;
    unsigned int color = 0;
    
    for(j = y; j < (y + logo_h); j++)
        for(i = x; i < (x + logo_w); i++)
        {
            red = *p++;
            green = *p++;
            blue = *p++;
            color = red << 16 | green << 8 | blue;
            draw_point(i, j, color);
        }
}

// 简单文本绘制函数（使用矩形模拟字母）
void draw_text_simple(int x, int y, const char* text, int color) {
    int len = strlen(text);
    for (int i = 0; i < len; i++) {
        char c = text[i];
        int char_x = x + i * 10;
        
        // 根据字符绘制不同的简单形状
        switch(c) {
            case 'A': case 'a':
                // 绘制A的形状
                draw_rectangle(char_x, y, char_x + 8, y + 2, color); // 顶部横线
                draw_rectangle(char_x, y + 3, char_x + 2, y + 12, color); // 左边竖线
                draw_rectangle(char_x + 6, y + 3, char_x + 8, y + 12, color); // 右边竖线
                draw_rectangle(char_x + 2, y + 6, char_x + 6, y + 7, color); // 中间横线
                break;
            case 'B': case 'b':
                // 绘制B的形状
                draw_rectangle(char_x, y, char_x + 6, y + 2, color); // 顶部横线
                draw_rectangle(char_x, y, char_x + 2, y + 12, color); // 左边竖线
                draw_rectangle(char_x + 4, y + 1, char_x + 6, y + 5, color); // 右上竖线
                draw_rectangle(char_x + 4, y + 7, char_x + 6, y + 11, color); // 右下竖线
                draw_rectangle(char_x + 2, y + 5, char_x + 4, y + 7, color); // 中间横线
                break;
            // 可以添加更多字符...
            default:
                // 默认绘制一个矩形块
                draw_rectangle(char_x, y, char_x + 8, y + 12, color);
                break;
        }
    }
}

// 重置BOSS函数
void reset_boss(struct boss *boss, int boss_index, int screen_width) {
    boss->x = screen_width / 2 - BOSS_WIDTH / 2;
    boss->y = 50;
    boss->width = BOSS_WIDTH;
    boss->height = BOSS_HEIGHT;
    boss->boss_index = boss_index;
    
    // 根据BOSS编号调整属性
    if (boss_index == 1) {
        boss->HP = BOSS_MAX_HP;
        boss->maxHP = BOSS_MAX_HP;
        boss->move_speed = 2.0;
        boss->boss_pic = gImage_boss1;  // 第一个BOSS的图片
        boss->pic_width = BOSS_WIDTH;
        boss->pic_height = BOSS_HEIGHT;
        boss->time_stop_duration = TIME_STOP_DURATION;
        boss->time_stop_cooldown = TIME_STOP_COOLDOWN;
    } else if (boss_index == 2) {
        boss->HP = BOSS_MAX_HP * 1.5;  // 第二个BOSS血量更高
        boss->maxHP = BOSS_MAX_HP * 1.5;
        boss->move_speed = 2.5;        // 第二个BOSS移动更快
        boss->boss_pic = gImage_boss2;  // 第二个BOSS的图片
        boss->pic_width = BOSS_WIDTH;
        boss->pic_height = BOSS_HEIGHT;
        boss->time_stop_duration = TIME_STOP_DURATION + 60;  // 第二个BOSS时间静止更长
        boss->time_stop_cooldown = TIME_STOP_COOLDOWN - 60;  // 冷却时间更短
    }
    
    boss->alive = 1;
    boss->move_dir = 1;
    boss->move_pattern = BOSS_MOVE_LEFT_RIGHT;
    boss->pattern_timer = 0;
    boss->move_angle = 0;
    boss->pattern_speed = 0.05;
    boss->pattern_param1 = 50;
    boss->pattern_param2 = 100;
    
    // 初始化时间静止相关
    boss->time_stop_active = 0;
    boss->time_stop_timer = 0;
    boss->flashing = 0;
    boss->flash_timer = 0;
    boss->flash_state = 0;
}

// 更新BOSS时间静止效果
void update_boss_time_stop(struct boss *boss, struct game_control *game, struct bullet bullets[], int bullet_count) {
    if (!boss->alive) return;
    
    // 检查是否需要激活时间静止（血量低于25%且冷却完毕）
    if (boss->HP < boss->maxHP / 4 && 
        !boss->time_stop_active && 
        boss->time_stop_timer <= 0) {
        
        boss->time_stop_active = 1;
        boss->time_stop_timer = boss->time_stop_duration;
        game->time_stop_effect = 1;
        game->time_stop_alpha = 0;
        boss->flashing = 1;
        boss->flash_timer = 0;
        boss->flash_state = 1;
    }
    
    // 如果时间静止激活
    if (boss->time_stop_active) {
        // 更新时间静止计时器
        boss->time_stop_timer--;
        
        // 更新全局时间静止效果透明度（淡入淡出）
        if (boss->time_stop_timer > boss->time_stop_duration * 0.8) {
            // 淡入阶段
            game->time_stop_alpha += 8;
            if (game->time_stop_alpha > 128) game->time_stop_alpha = 128;
        } else if (boss->time_stop_timer < boss->time_stop_duration * 0.2) {
            // 淡出阶段
            game->time_stop_alpha -= 8;
            if (game->time_stop_alpha < 0) game->time_stop_alpha = 0;
        }
        
        // 更新BOSS闪烁效果
        boss->flash_timer++;
        if (boss->flash_timer >= FLASH_DURATION) {
            boss->flash_timer = 0;
            boss->flash_state = !boss->flash_state;
        }
        
        // 冻结所有子弹（时间静止时子弹停止移动）
        for (int i = 0; i < bullet_count; i++) {
            if (bullets[i].x >= 0 && bullets[i].y >= 0) {
                bullets[i].frozen = 1;
            }
        }
        
        // 时间静止结束
        if (boss->time_stop_timer <= 0) {
            boss->time_stop_active = 0;
            game->time_stop_effect = 0;
            boss->flashing = 0;
            boss->time_stop_timer = boss->time_stop_cooldown;  // 开始冷却
            
            // 解冻所有子弹
            for (int i = 0; i < bullet_count; i++) {
                bullets[i].frozen = 0;
            }
        }
    } else if (boss->time_stop_timer > 0) {
        // 更新时间静止冷却
        boss->time_stop_timer--;
    }
}

// 创建爆炸效果
void create_explosion(struct explosion explosions[], int x, int y, int type) {
    for (int i = 0; i < 10; i++) {
        if (!explosions[i].active) {
            explosions[i].x = x;
            explosions[i].y = y;
            explosions[i].frame = 0;
            explosions[i].active = 1;
            explosions[i].type = type;
            break;
        }
    }
}

