// 绘制游戏信息
void draw_game_info(struct game_control *game, struct warplane *player, struct boss *boss, int screen_width) {
    // 绘制玩家血条
    if (player->active) {
        draw_health_bar(10, 10, 200, 15, player->HP, player->maxHP, 0xFFFFFF, 0x555555, 0x00FF00);
    }
    
    // 绘制BOSS血条和编号
    if (boss->alive) {
        int boss_bar_x = screen_width - 210;
        draw_health_bar(boss_bar_x, 10, 200, 15, boss->HP, boss->maxHP, 0xFFFFFF, 0x555555, 0xFF0000);
        
        // 绘制BOSS编号
        char boss_num_text[20];
        sprintf(boss_num_text, "BOSS %d", boss->boss_index);
        draw_rectangle(boss_bar_x - 60, 10, boss_bar_x - 10, 25, 0x000000); // 清除区域
        // 用颜色块表示BOSS编号
        int boss_num_color = (boss->boss_index == 1) ? 0x00FFFF : 0xFF00FF;
        draw_rectangle(boss_bar_x - 60, 10, boss_bar_x - 10, 25, boss_num_color);
    }
    
    // 绘制分数
    char score_text[30];
    sprintf(score_text, "SCORE: %d", game->player_score);
    draw_rectangle(screen_width/2 - 60, 10, screen_width/2 + 60, 25, 0x000000); // 清除区域
    // 用颜色条表示分数
    int score_bar_width = 100 * game->player_score / 1000; // 假设1000分满
    if (score_bar_width > 100) score_bar_width = 100;
    draw_rectangle(screen_width/2 - 50, 12, screen_width/2 - 50 + score_bar_width, 23, 0xFFFF00);
    
    // 绘制BOSS进度
    char progress_text[30];
    sprintf(progress_text, "BOSS: %d/%d", game->boss_count, game->total_bosses);
    draw_rectangle(screen_width/2 - 60, 30, screen_width/2 + 60, 45, 0x000000); // 清除区域
    // 用颜色条表示进度
    int progress_width = 100 * game->boss_count / game->total_bosses;
    draw_rectangle(screen_width/2 - 50, 32, screen_width/2 - 50 + progress_width, 43, 0x00FFFF);
}

// 绘制血条函数
void draw_health_bar(int x, int y, int width, int height, int currentHP, int maxHP, int border_color, int bg_color, int health_color) {
    // 绘制边框
    draw_rectangle(x, y, x + width - 1, y + height - 1, border_color);
    
    // 绘制背景
    draw_rectangle(x + 1, y + 1, x + width - 2, y + height - 2, bg_color);
    
    // 计算血量长度
    if (currentHP > 0) {
        int health_width = (width - 2) * currentHP / maxHP;
        if (health_width > 0) {
            draw_rectangle(x + 1, y + 1, x + health_width, y + height - 2, health_color);
        }
    }
}

// 碰撞检测函数
int check_collision(int x1, int y1, int w1, int h1, int x2, int y2, int w2, int h2) {
    return (x1 < x2 + w2 &&
            x1 + w1 > x2 &&
            y1 < y2 + h2 &&
            y1 + h1 > y2);
}

// BOSS更新运动轨迹函数
void update_boss_movement(struct boss *boss, int screen_width, int screen_height, struct warplane *player, int frame_count) {
    if (!boss->alive) return;
    
    // 每300帧（约2.4秒）切换一次运动模式
    if (frame_count % 300 == 0) {
        boss->move_pattern = rand() % BOSS_MOVE_PATTERNS_COUNT;
        boss->pattern_timer = 0;
        boss->move_angle = 0;
        
        // 根据模式设置参数
        switch (boss->move_pattern) {
            case BOSS_MOVE_LEFT_RIGHT:
                boss->move_dir = (rand() % 2) ? 1 : -1;  // 随机初始方向
                boss->move_speed = 2 + (rand() % 3);     // 速度2-4
                break;
            case BOSS_MOVE_UP_DOWN:
                boss->move_dir = (rand() % 2) ? 1 : -1;
                boss->move_speed = 2 + (rand() % 3);
                break;
            case BOSS_MOVE_CIRCLE:
                boss->move_angle = 0;
                boss->pattern_speed = 0.05 + (rand() % 10) * 0.01;  // 0.05-0.15
                break;
            case BOSS_MOVE_SINE:
                boss->move_angle = 0;
                boss->pattern_param1 = 50 + rand() % 100;  // 振幅
                boss->pattern_param2 = 50 + rand() % 100;  // 中心Y坐标
                boss->pattern_speed = 0.03 + (rand() % 10) * 0.01;
                boss->move_speed = 1 + rand() % 3;
                break;
            case BOSS_MOVE_EIGHT:
                boss->move_angle = 0;
                boss->pattern_speed = 0.03 + (rand() % 10) * 0.01;
                break;
            case BOSS_MOVE_SPIRAL:
                boss->move_angle = 0;
                boss->pattern_param1 = 50;  // 初始半径
                boss->pattern_speed = 0.05;
                break;
            case BOSS_MOVE_RANDOM:
                boss->move_speed = 2 + (rand() % 3);
                break;
            case BOSS_MOVE_CHASE:
                boss->move_speed = 1 + (rand() % 2);
                break;
        }
    }
    
    boss->pattern_timer++;
    
    // 根据不同模式更新位置
    switch (boss->move_pattern) {
        case BOSS_MOVE_LEFT_RIGHT:  // 左右移动，碰壁反弹
            boss->x += boss->move_dir * boss->move_speed;
            if (boss->x <= 0 || boss->x + boss->width >= screen_width) {
                boss->move_dir = -boss->move_dir;
            }
            break;
            
        case BOSS_MOVE_UP_DOWN:  // 上下移动，碰壁反弹
            boss->y += boss->move_dir * boss->move_speed;
            if (boss->y <= 30 || boss->y + boss->height >= screen_height / 2) {
                boss->move_dir = -boss->move_dir;
            }
            break;
            
        case BOSS_MOVE_CIRCLE:  // 圆周运动
            boss->move_angle += boss->pattern_speed;
            if (boss->move_angle > 2 * PI) boss->move_angle -= 2 * PI;
            
            // 圆周运动中心点
            int circle_center_x = screen_width / 2;
            int circle_center_y = screen_height / 4;
            int circle_radius = 150;
            
            boss->x = circle_center_x + circle_radius * cos(boss->move_angle) - boss->width / 2;
            boss->y = circle_center_y + circle_radius * sin(boss->move_angle) - boss->height / 2;
            
            // 确保在屏幕内
            if (boss->x < 0) boss->x = 0;
            if (boss->x + boss->width >= screen_width) boss->x = screen_width - boss->width - 1;
            if (boss->y < 30) boss->y = 30;
            if (boss->y + boss->height >= screen_height / 2) boss->y = screen_height / 2 - boss->height - 1;
            break;
            
        case BOSS_MOVE_SINE:  // 正弦波运动
            boss->move_angle += boss->pattern_speed;
            if (boss->move_angle > 2 * PI) boss->move_angle -= 2 * PI;
            
            boss->x += boss->move_speed;
            boss->y = boss->pattern_param2 + boss->pattern_param1 * sin(boss->move_angle);
            
            // 边界检测和反弹
            if (boss->x <= 0) {
                boss->x = 0;
                boss->move_speed = fabs(boss->move_speed);
            }
            if (boss->x + boss->width >= screen_width) {
                boss->x = screen_width - boss->width - 1;
                boss->move_speed = -fabs(boss->move_speed);
            }
            if (boss->y <= 30) boss->y = 30;
            if (boss->y + boss->height >= screen_height / 2) boss->y = screen_height / 2 - boss->height - 1;
            break;
            
        case BOSS_MOVE_EIGHT:  // 8字运动
            boss->move_angle += boss->pattern_speed;
            if (boss->move_angle > 4 * PI) boss->move_angle -= 4 * PI;
            
            {
                // Lissajous曲线，形成8字
                float t = boss->move_angle;
                int radius_x = 100;
                int radius_y = 50;
                boss->x = screen_width / 2 + radius_x * sin(t) - boss->width / 2;
                boss->y = screen_height / 4 + radius_y * sin(2 * t) - boss->height / 2;
                
                // 确保在屏幕内
                if (boss->x < 0) boss->x = 0;
                if (boss->x + boss->width >= screen_width) boss->x = screen_width - boss->width - 1;
                if (boss->y < 30) boss->y = 30;
                if (boss->y + boss->height >= screen_height / 2) boss->y = screen_height / 2 - boss->height - 1;
            }
            break;
            
        case BOSS_MOVE_SPIRAL:  // 螺旋运动
            boss->move_angle += boss->pattern_speed;
            if (boss->move_angle > 4 * PI) {
                boss->move_angle = 0;
                boss->pattern_param1 = 50;  // 重置半径
            }
            
            {
                float radius = boss->pattern_param1 + boss->move_angle * 5;  // 半径随时间增加
                boss->x = screen_width / 2 + radius * cos(boss->move_angle) - boss->width / 2;
                boss->y = screen_height / 4 + radius * sin(boss->move_angle) - boss->height / 2;
                
                // 边界检测
                if (boss->x < 0) boss->x = 0;
                if (boss->x + boss->width >= screen_width) boss->x = screen_width - boss->width - 1;
                if (boss->y < 30) boss->y = 30;
                if (boss->y + boss->height >= screen_height / 2) boss->y = screen_height / 2 - boss->height - 1;
            }
            break;
            
        case BOSS_MOVE_RANDOM:  // 随机移动
            if (boss->pattern_timer % 30 == 0) {  // 每30帧随机改变方向
                boss->move_dir = (rand() % 2) ? 1 : -1;
                // 随机决定移动X轴还是Y轴
                if (rand() % 2) {
                    boss->x += boss->move_dir * boss->move_speed;
                } else {
                    boss->y += boss->move_dir * boss->move_speed;
                }
            }
            
            // 边界检测和反弹
            if (boss->x <= 0) boss->x = 0;
            if (boss->x + boss->width >= screen_width) boss->x = screen_width - boss->width - 1;
            if (boss->y <= 30) boss->y = 30;
            if (boss->y + boss->height >= screen_height / 2) boss->y = screen_height / 2 - boss->height - 1;
            break;
            
        case BOSS_MOVE_CHASE:  // 追逐玩家（但不会离开上半屏）
            {
                int target_x = player->x + WARFLANE/2 - boss->width/2;
                int target_y = player->y / 3;  // 只追逐到屏幕上半部分
                
                if (boss->x < target_x) boss->x += boss->move_speed;
                if (boss->x > target_x) boss->x -= boss->move_speed;
                if (boss->y < target_y) boss->y += boss->move_speed;
                if (boss->y > target_y) boss->y -= boss->move_speed;
                
                // 边界检测
                if (boss->x < 0) boss->x = 0;
                if (boss->x + boss->width >= screen_width) boss->x = screen_width - boss->width - 1;
                if (boss->y < 30) boss->y = 30;
                if (boss->y + boss->height >= screen_height / 2) boss->y = screen_height / 2 - boss->height - 1;
            }
            break;
    }
}



